import {createContext, useCallback, use, useMemo, useRef, useState} from 'react'
import {Banner, Button, Link} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {DownloadIcon, LinkExternalIcon, ArrowRightIcon} from '@primer/octicons-react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import styles from './TbbAnnouncementBanner.module.css'

const USAGE_REPORT_LAST_MONTH_PERIOD = 2
const USAGE_REPORT_PREMIUM_REQUEST_TYPE = 3

// ─── Props from Rails ───────────────────────────────────────────────────────────

export interface TbbAnnouncementBannerPartialProps {
  budgetsPath: string
  usageReportPath: string
  currentUserEmail?: string
}

// ─── Notification context ───────────────────────────────────────────────────────

type Notification = {id: string; type: 'success' | 'warning' | 'error'; message: string}

const NotificationContext = createContext<{
  addNotification: (n: Notification) => void
  notifications: Notification[]
}>({addNotification: () => {}, notifications: []})

// ─── Preview dialog ─────────────────────────────────────────────────────────────

interface PreviewDialogProps {
  budgetsPath: string
  usageReportPath: string
  currentUserEmail?: string
  onClose: () => void
  returnFocusRef: React.RefObject<HTMLButtonElement | null>
}

function PreviewDialog({budgetsPath, usageReportPath, currentUserEmail, onClose, returnFocusRef}: PreviewDialogProps) {
  const {addNotification} = use(NotificationContext)
  const [isDownloading, setIsDownloading] = useState(false)

  const handleDownloadCsv = useCallback(async () => {
    setIsDownloading(true)
    try {
      const response = await verifiedFetchJSON(usageReportPath, {
        method: 'POST',
        body: {period: USAGE_REPORT_LAST_MONTH_PERIOD, type: USAGE_REPORT_PREMIUM_REQUEST_TYPE},
      })

      if (response.ok) {
        addNotification({
          id: crypto.randomUUID(),
          type: 'success',
          message: currentUserEmail
            ? `We're preparing your usage report. We'll send an email to ${currentUserEmail} when it's ready.`
            : "We're preparing your usage report. We'll send an email when it's ready.",
        })
      } else {
        let responseData = null
        try {
          responseData = await response.json()
        } catch {
          // ignore parse errors
        }

        if (responseData?.code === 'IN_PROGRESS') {
          addNotification({
            id: crypto.randomUUID(),
            type: 'warning',
            message: currentUserEmail
              ? `Your request was not processed because you have a pending usage report request. Check ${currentUserEmail} for the report when it's ready.`
              : 'Your request was not processed because you have a pending usage report request.',
          })
        } else {
          addNotification({
            id: crypto.randomUUID(),
            type: 'error',
            message: 'There was an issue preparing your usage report. Please try again.',
          })
        }
      }
    } catch {
      addNotification({
        id: crypto.randomUUID(),
        type: 'error',
        message: 'There was an issue preparing your usage report. Please try again.',
      })
    } finally {
      setIsDownloading(false)
      onClose()
    }
  }, [addNotification, currentUserEmail, usageReportPath, onClose])

  return (
    <Dialog
      onClose={onClose}
      title="Preview your AI credit usage"
      returnFocusRef={returnFocusRef}
      aria-labelledby="preview-bill-header"
      width="xlarge"
    >
      <Banner variant="info" hideTitle title="Upcoming AI credits billing change" className="tmp-mb-3">
        <Banner.Description>Insights are estimated and do not represent your actual bill.</Banner.Description>
      </Banner>

      <p className={styles.introText}>
        Starting June 1, 2026, Copilot usage will be measured and billed in AI credits instead of premium request units.
        Preview how your past usage maps to AI credits using the tools below.
      </p>

      <div className={styles.prepareSection}>
        <p className={styles.prepareSectionHeading}>Prepare for the upcoming change</p>

        <Link
          href="https://gh.io/ghcp-billing-preview-docs"
          target="_blank"
          rel="noopener noreferrer"
          className={styles.prepareCard}
          data-testid="preview-bill-docs-link"
        >
          <span className={styles.prepareCardTitle}>
            Refer to documentation <ArrowRightIcon size={16} />
          </span>
          <span className={styles.prepareCardDescription}>
            Explore and learn how AI credits work and how to optimize your usage.
          </span>
        </Link>

        <Link href={budgetsPath} className={styles.prepareCard} data-testid="preview-bill-set-budget-link">
          <span className={styles.prepareCardTitle}>
            Set a budget <ArrowRightIcon size={16} />
          </span>
          <span className={styles.prepareCardDescription}>
            Your existing Premium request budgets will be migrated to AI credits. Review and adjust as needed to
            prepare.
          </span>
        </Link>
      </div>

      <p className={styles.supportText}>
        Have questions?{' '}
        <Link
          href="https://support.github.com"
          target="_blank"
          rel="noopener noreferrer"
          inline
          data-testid="preview-bill-support-link"
        >
          Reach out to us
        </Link>{' '}
        for help with your transition.
      </p>

      <div className={styles.dialogFooter}>
        <div className={styles.footerActionGroup}>
          <p className={styles.footerActionHelper}>
            Download the CSV report of your premium request usage, which now includes new columns converting past data
            to AI credits.
          </p>
          <Button
            className={styles.footerAction}
            variant="primary"
            leadingVisual={<DownloadIcon />}
            onClick={handleDownloadCsv}
            disabled={isDownloading}
            data-testid="preview-bill-download-csv"
          >
            {isDownloading ? 'Preparing report…' : 'Download CSV'}
          </Button>
        </div>
        <div className={styles.footerActionGroup}>
          <p className={styles.footerActionHelper}>Use the preview app to explore the CSV interactively.</p>
          <Button
            className={styles.footerAction}
            as="a"
            href="https://copilot-billing-preview.github.com/"
            target="_blank"
            rel="noopener noreferrer"
            leadingVisual={<LinkExternalIcon />}
            data-testid="preview-bill-full-preview-link"
          >
            Explore usage and trends
          </Button>
        </div>
      </div>
    </Dialog>
  )
}

// ─── Notification banner ────────────────────────────────────────────────────────

const NOTIFICATION_VARIANT_MAP = {
  success: 'success',
  warning: 'warning',
  error: 'critical',
} as const

function NotificationBanner({message, type}: Notification) {
  const [isVisible, setIsVisible] = useState(true)
  if (!isVisible) return null

  return (
    <div aria-live="polite" aria-atomic="true">
      <Banner
        variant={NOTIFICATION_VARIANT_MAP[type]}
        hideTitle
        /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
        title="Preview Bill Notification"
        onDismiss={() => setIsVisible(false)}
        className="tmp-mb-3"
      >
        <Banner.Description>{message}</Banner.Description>
      </Banner>
    </div>
  )
}

// ─── Main partial component ─────────────────────────────────────────────────────

export function TbbAnnouncementBannerPartial({
  budgetsPath,
  usageReportPath,
  currentUserEmail,
}: TbbAnnouncementBannerPartialProps) {
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const returnFocusRef = useRef<HTMLButtonElement>(null)

  const addNotification = useCallback((n: Notification) => {
    setNotifications(prev => [...prev, n])
  }, [])

  const ctx = useMemo(() => ({addNotification, notifications}), [addNotification, notifications])

  const handleOpen = useCallback(() => {
    setIsDialogOpen(true)
  }, [])

  const handleClose = useCallback(() => {
    setIsDialogOpen(false)
  }, [])

  const lastNotification = notifications.at(-1)

  return (
    <NotificationContext value={ctx}>
      {lastNotification && <NotificationBanner key={lastNotification.id} {...lastNotification} />}

      <div className={styles.banner} data-testid="tbb-announcement-banner">
        <h2 className={styles.bannerTitle}>GitHub Copilot is moving to AI credits</h2>
        <p className={styles.bannerDescription}>
          Starting June 1, 2026 Copilot usage will be measured and billed in AI credits instead of Premium request
          units. AI credits give you more granular visibility into your usage across models and features. Preview how
          this change will affect your billing based on your recent usage.
        </p>
        <div className={styles.bannerActions}>
          <Button ref={returnFocusRef} onClick={handleOpen} variant="primary" data-testid="preview-bill-button">
            Preview your usage
          </Button>
          <Link
            href="https://gh.io/copilot-billing-blog"
            target="_blank"
            rel="noopener noreferrer"
            className={styles.blogLink}
            data-testid="tbb-blog-link"
          >
            Read the blog post
          </Link>
        </div>
      </div>

      {isDialogOpen && (
        <PreviewDialog
          budgetsPath={budgetsPath}
          usageReportPath={usageReportPath}
          currentUserEmail={currentUserEmail}
          onClose={handleClose}
          returnFocusRef={returnFocusRef}
        />
      )}
    </NotificationContext>
  )
}
